\u0048\u002f\u0065\u002b\u002f\u005e\u0075\u0060\u0046\u0032\u004f\u007c\u0034\u006a\u0046\u0026\u0035\u006b\u007e\u0026\u007c\u007e\u0021\u004c\u0069\u003a\u0031\u0047\u006e\u0036\u0025\u006a\u0025\u0057\u0072\u0044\u003c\u003e\u003c\u002c\u003d\u006f\u0065\u007e\u0076\u004c\u0038\u002e\u0044\u0025\u002b\u004f\u002a\u0052\u0074\u002f\u0045\u0045\u0060\u006c\u0064\u007b\u0024\u0070\u003e\u007c\u0055\u0076\u003b\u0071\u0049\u0069\u0020\u005d\u004c\u0057\u0030\u005b\u0044\u0030\u003a\u0060\u0067\u004e\u0078\u0074\u0047\u0037\u005c\u007e\u0054\u0061\u002c\u0067\u0068\u005b\u0065\u0037\u006a\u0078\u0067\u0033\u005c\u0048\u0065\u0032\u0047\u004f\u0076\u005a\u0028\u0032\u0061\u0058\u0032\u006b\u003e\u006f\u0033\u0049\u0033\u005e\u0060\u0032\u002d\u006a\u002c\u006f\u0052\u0065\u003a\u0055\u0059\u007d\u004a\u0058\u005d\u003a\u005c\u0039\u006f\u002d\u0065\u0047\u004a\u0046\u0023\u0062\u0068\u0048\u0050\u004f\u0066\u003b\u0072\u007d\u006b\u002d\u002e\u0026\u006d\u004e\u0042\u005e\u002d\u0074\u0033\u004b\u003e\u005d\u004c\u007a\u007d\u003e\u003e\u0058\u0030\u0044\u0054\u0053\u0029\u0050\u0022\u0033\u0041\u002f\u0054\u004d\u0055\u0044\u0076\u0048\u0073\u0062\u007e\u0066\u0052\u0051\u0062\u0037\u007e\u0072\u002d\u0079\u0020\u005d\u0024\u0046\u003a\u004d\u005c\u002a\u0074\u0021\u0078\u0029\u0053\u0064\u0054\u0038\u0037\u0062\u0058\u0031\u0046\u0050\u004d\u0021\u006c\u0035\u004d\u0026\u004c\u003c\u0021\u003b\u002f\u003e\u0062\u004e\u006d\u005d\u0040\u0054\u006b\u0049\u002a\u002c\u0072\u0066\u005e\u003a\u004a\u005b\u0047\u0074\u0069\u0077\u006a\u002e\u005c\u006f\u0075\u006c\u0042\u0061\u0026\u0040\u0051\u0049\u003b\u003c\u0074\u0047\u006e\u007b\u0042\u0062\u0079\u0026\u002e\u005b\u006a\u0045\u006c\u0070\u006a\u0035\u0049\u0030\u0034\u003f\u0043\u0026\u0032\u007d\u0045\u0077\u0028\u004b\u0077\u0039\u0065\u0045\u005e\u0053\u0074\u005f\u006d\u0028\u0028\u002f\u002c\u004b\u006f\u007e\u0041\u0034\u0040\u0033\u0037\u0060\u003e\u006d\u0065\u0028\u0036\u0021\u0078\u0070\u004d\u0050\u0043\u0073\u0042\u0070\u006c\u005d\u0037\u0020\u0076\u006e\u007d\u003b\u0034\u0079\u007a\u006b\u0025\u007e\u003a\u0042\u0056\u0078\u003c\u0053\u003b\u0077\u002d\u003c\u0032\u007b\u0078\u006d\u006d\u007c\u002f\u0031\u004d\u0068\u0029\u0064\u003d\u0076\u0049\u0056\u0047\u003b\u0025\u0037\u007b\u003b\u0065\u006a\u006d\u003f\u004c\u0034\u0047\u003b\u005e\u0039\u0040\u0071\u0024\u0024\u006e\u0073\u004f\u0040\u0070\u006a\u006f\u0056\u0074\u0072\u0037\u003f\u0058\u003f\u0077\u0049\u0021\u0036\u006b\u0067\u0062\u0023\u0057\u0065\u0024\u005a\u0065\u005d\u003a\u0039\u002e\u0075\u002a\u0061\u005f\u004d\u0078\u0053\u0066\u005c\u0067\u0041\u007a\u0068\u003c\u002e\u003d\u0046\u0079\u002a\u0056\u0062\u003b\u0021\u0058\u0060\u002a\u0068\u005c\u004e\u0058\u007a\u003d\u0073\u007a\u0061\u0030\u005f\u0051\u0070\u0058\u0050\u003a\u0025\u0040\u0025\u0072\u0028\u0071\u0050\u0078\u0054\u0059\u0060\u0052\u0028\u0044\u0045\u0035\u0038\u0046\u007a\u0073\u002e\u0057\u0027\u0078\u0031\u0031\u0079\u0027\u003b\u003a\u0022\u003a\u0029\u004a\u003c\u0054\u006c\u0069\u005a\u0050\u0040\u002d\u0043\u0056\u0045\u0065\u006d\u0044\u004b\u0025\u0073\u006f\u0033\u0064\u005d\u0060\u0027\u002c\u007c\u006e\u003f\u006a\u003f\u0038\u0076\u0074\u006a\u004f\u0030\u005f\u0041\u0040\u0069\u006e\u0037\u0040\u0025\u0059\u006d\u0073\u0050\u0077\u002c\u0066\u005a\u0033\u0053\u002f\u0065\u0076\u0073\u003d\u0067\u0065\u006a\u002c\u0030\u004d\u0078\u0058\u004a\u0030\u0076\u0023\u0072\u0032\u0076\u002d\u0062\u003e\u0076\u002d\u0047\u0029\u0041\u004f\u0072\u0033\u0049\u0048\u0052\u0065\u0044\u0070\u004a\u007d\u0042\u006f\u0078\u0041\u0050\u006a\u005b\u0040\u0048\u0036\u004c\u002f\u0033\u0054\u0048\u005a\u005b\u0068\u0023\u0045\u007c\u0044\u0074\u0048\u0032\u0051\u003a\u0022\u005a\u006b\u0059\u0033\u0047\u0030\u0044\u002e\u006f\u0057\u0047\u004d\u0066\u003e\u0021\u0032\u003e\u0061\u0025\u006b\u005d\u0026\u0033\u0074\u004f\u007b\u003f\u005f\u005f\u007b\u002e\u0037\u0036\u002e\u0033\u0021\u0022\u005c\u0030\u0022\u002e\u0062\u0039\u002a\u0070\u0062\u0026\u0031\u0053\u003e\u007e\u0040\u005c\u004b\u0021\u007e\u003e\u0049\u0037\u004e\u0047\u007d\u004b\u0063\u0050\u0068\u007c\u007b\u0049\u006c\u003f\u006b\u0025\u002e\u0044\u0061\u0026\u002c\u0076\u0045\u004f\u007e\u003c\u0065\u0045\u0026\u004b\u006e\u0027\u005c\u0024\u0057\u005c\u0025\u005b\u002d\u0032\u0051\u0060\u0035\u004f\u0072\u002e\u006b\u0077\u002c\u0058\u004b\u0030\u0063\u0065\u0022\u0044\u006e\u0062\u0054\u0049\u002e\u007e\u0026\u005e\u006b\u0048\u0046\u002a\u006d\u0027\u003a\u005b\u006a\u0071\u0063\u0050\u005c\u0037\u0069\u0029\u0067\u0058\u007d\u0068\u003a\u003f\u0069\u003b\u0046\u0024\u004c\u005c\u0067\u0075\u005f\u0075\u004f\u0060\u0022\u0055\u0058\u0065\u006e\u0068\u0064\u0033\u006e\u0038\u005e\u0079\u0039\u0078\u0075\u007e\u0032\u0075\u0020\u0077\u0072\u0042\u003f\u007b\u0079\u0044\u006c\u006c\u004b\u006e\u0076\u0066\u0067\u0041\u0052\u007e\u0068\u002a\u002a\u0047\u0045\u006c\u0031\u0060\u0032\u0022\u0063\u0024\u0030\u0069\u0069\u0025\u0062\u005b\u0070\u0044\u005c\u0039\u0045\u0053\u0048\u0052\u0028\u006e\u0078\u0036\u002f\u0042\u0052\u006b\u0020\u0074\u005e\u003c\u005a\u0038\u0066\u006e\u0038\u0020\u0058\u003a\u006a\u0029\u0050\u0063\u0038\u007a\u006e\u0047\u0026\u0033\u002e\u0070\u0069\u0051\u0078\u0063\u005f\u007b\u004b\u0065\u003f\u0066\u0040\u0031\u0045\u005b\u0040\u003e\u0025\u003a\u0055\u0044\u007e\u0047\u004a\u0040\u0074\u0058\u002b\u005c\u0020\u0065\u0021\u0035\u004b\u0050\u0042\u0069\u003c\u0026\u003e\u002a\u005d\u005e\u0065\u005a\u005b\u0058\u0021\u0068\u002c\u0025\u0033\u0021\u0063\u0066\u0025\u0038\u0041\u0036\u0049\u004f\u0023\u007d\u002c\u0046\u0040\u005a\u007e\u0054\u0077\u006f\u0072\u0041\u0060\u0056\u007c\u0032\u002b\u0048\u0043\u004c\u0020\u003d\u002a\u0055\u0053\u006c\u006d\u0077\u0025\u0062\u0043\u004d\u006d\u0072\u0056\u007d\u005b\u0025\u0038\u0035\u0058\u0056\u0071\u0034\u0030\u007a\u004e\u0020\u0035\u0021\u0040\u0069\u006f\u004b\u007e\u006d\u0076\u002c\u0050\u0049\u0067\u0060\u0035\u0037\u0061\u0031\u003c\u0056\u0073\u0072\u0077\u0049\u0063\u0064\u0068\u0026\u004d\u0076\u0071\u0066\u0056\u006c\u0077\u0067\u0067\u0028\u0069\u007e\u002a\u0060\u0043\u0072\u0072\u006e\u0043\u0030\u0078\u002c\u0037\u0071\u0051\u0061\u007c\u0035\u002b\u006e\u004c\u0022\u007b\u0057\u0026\u0074\u0071\u006d\u003b\u002e\u0063\u0051\u005b\u0022\u0049\u0030\u007c\u002a\u005d\u0064\u0042\u0040\u0072\u007a\u0020\u0043\u005a\u0070\u003b\u007c\u0023\u007a\u0024\u0054\u004e\u0051\u0024\u006e\u004f\u0031\u0040\u0067\u0034\u004a\u006a\u007c\u006e\u0076\u0069\u0065\u006f\u0060\u0021\u002a\u0035\u0029\u0057\u0066\u004b\u006e\u0072\u0038\u0074\u003c\u003a\u0075\u0032\u003f\u0069\u004a\u0032\u003a\u0042\u0079\u0032\u006d\u003f\u0031\u0079\u0044\u0061\u0073\u006f\u006b\u0038\u004b\u003c\u0074\u0023\u0035\u0022\u0027\u0054\u0049\u0055\u0063\u0049\u0048\u0021\u0073\u0027\u0020\u0075\u0048\u004b\u0044\u007a\u006c\u0071\u0025\u0053\u0051\u0020\u0033\u005e\u0024\u0074\u002d\u0043\u0040\u0066\u0040\u0056\u0032\u004a\u005b\u004c\u0034\u004c\u0058\u006d\u003b\u007a\u0043\u0045\u0040\u0073\u0079\u002d\u002d\u005b\u0030\u0078\u0034\u0061\u004a\u002f\u0046\u002e\u005f\u006f\u0022\u0032\u0030\u0067\u0027\u0048\u0063\u003b\u0045\u004e\u007d\u004e\u006e\u0075\u0024\u006b\u002c\u007d\u006c\u007b\u0039\u0052\u0024\u0036\u0040\u0021\u0075\u003c\u007a\u0027\u0064\u0062\u007a\u0034\u0077\u0059\u0048\u0062\u003f\u0063\u004c\u006e\u0025\u0031\u004c\u0078\u006e\u006c\u0071\u0026\u0030\u003d\u0058\u0069\u0054\u006e\u0032\u0041\u0020\u0038\u005f\u0034\u0032\u0072\u0071\u0020\u0052\u005c\u006d\u0073\u007b\u003e\u0027\u005a\u006c\u003e\u0065\u0057\u0042\u0027\u0075\u006e\u0021\u0039\u0023\u0067\u0039\u0060\u0052\u0047\u0041\u006b\u0059\u0058\u004f\u0065\u004b\u0047\u006b\u0028\u0044\u005a\u0049\u004e\u0031\u0030\u0043\u0028\u0055\u004f\u002a\u0047\u004a\u0022\u0074\u0067\u005e\u0073\u0059\u0062\u0076\u0059\u005d\u003f\u0072\u0048\u0072\u0053\u005e\u005d\u0068\u002e\u0069\u0055\u0055\u002e\u0034\u005b\u006a\u0055\u0060\u007b\u005d\u0029\u0064\u0023\u0070\u0052\u006a\u0030\u0065\u0046\u006c\u0075\u004e\u005e\u006c\u006a\u0044\u0020\u0055\u005e\u0053\u0024\u0046\u0068\u004b\u005e\u006f\u0066\u0073\u002d\u0070\u004f\u0050\u0061\u0069\u007a\u0022\u0075\u0040\u0072\u0065\u0070\u004a\u0026\u005b\u007e\u0040\u0025\u003a\u0069\u0042\u0066\u007b\u0025\u0034\u0039\u0038\u0072\u004f\u0066\u0033\u0031\u002a\u0028\u005c\u005c\u0063\u0028\u0073\u0071\u002d\u003e\u0036\u0068\u0053\u0070\u0048\u0040\u005f\u006b\u0048\u003d\u0068\u0023\u0046\u0049\u002e\u004c\u002b\u005e\u006a\u0054\u0020\u0065\u0056\u006c\u0043\u005e\u0020\u0058\u0025\u0021\u0028\u003c\u0066\u0027\u0050\u0061\u003f\u0058\u0033\u0063\u0025\u0053\u0038\u005f\u002a\u0038\u0053\u005c\u005c\u0025\u0048\u0079\u006f\u005a\u0049\u0076\u0056\u0073\u003a\u0078\u0025\u0066\u0029\u006f\u006d\u0038\u0021\u0070\u006f\u0054\u0038\u004a\u005a\u0043\u002b\u004d\u0029\u0050\u0038\u0062\u0054\u006a\u006a\u003c\u0047\u0078\u0068\u0046\u0043\u0025\u0072\u0055\u0071\u005d\u006f\u0023\u0075\u003d\u0059\u003e\u0036\u0047\u0049\u0073\u0022\u0063\u004e\u0071\u0031\u003f\u0062\u006e\u0064\u0033\u0070\u0020\u005b\u002d\u0036\u0041\u0078\u006e\u0050\u004e\u0066\u003d\u005e\u0027\u002f\u005c\u004d\u0057\u0067\u0070\u0035\u007b\u005b\u007b\u0028\u0063\u0026\u0022\u0060\u0055\u003f\u005f\u006d\u002a\u0078\u0044\u003c\u0050\u005d\u003d\u006b\u0069\u0051\u006c\u0038\u0044\u002b\u0077\u0056\u0057\u003a\u0062\u0051\u006d\u0042\u007b\u0037\u007e\u0046\u0041\u0066\u0031\u004b\u0054\u003d\u0042\u004b\u0025\u0026\u0078\u004c\u0032\u0079\u0050\u0062\u0065\u003d\u003b\u003a\u007b\u003b\u003c\u0060\u007e\u004d\u0054\u003f\u0033\u003d\u0063\u0048\u0056\u0028\u002e\u0023\u0054\u0035\u006f\u003c\u005f\u004b\u0061\u0070\u0066\u003d\u0028\u002e\u003b\u0056\u003f\u0032\u0065\u0078\u0031\u0049\u003a\u0077\u0055\u007b\u007b\u003a\u0037\u003f\u0022\u0061\u004b\u0025\u004c\u0044\u0021\u0075\u004b\u002a\u002a\u0063\u002a\u002c\u007d\u0047\u0043\u0053\u0020\u0071\u0046\u0073\u0026\u004d\u0041\u0071\u0028\u0037\u007b\u005c\u0027\u0066\u007e\u0050\u003f\u006f\u0068\u0030\u004e\u0021\u002c\u007b\u005c\u0036\u0066\u007b\u006b\u006a\u0029\u0028\u002b\u0059\u0079\u0071\u007c\u0054\u0061\u0060\u006e\u0029\u0074\u004d\u0078\u0068\u0073\u0072\u0038\u004f\u0048\u007a\u006b\u0051\u004e\u002c\u007b\u0037\u0064\u0028\u0076\u005d\u002a\u0065\u005b\u005e\u0031\u005c\u002e\u0050\u0023\u0037\u004e\u005c\u0069\u006f\u004d\u0035\u0038\u004a\u0073\u005b\u007b\u0043\u003d\u0034\u0035\u005e\u0077\u0070\u0045\u0047\u0078\u0022\u0026\u003c\u0040\u0028\u006a\u0036\u0068\u0075\u0046\u006e\u0076\u0068\u0042\u0052\u005e\u003d\u0070\u0051\u0060\u0057\u003f\u0024\u004f\u004b\u0073\u0064\u002d\u005c\u002f\u002f\u0028\u007e\u006c\u004f\u0048\u0022\u004d\u004e\u0028\u0031\u0047\u0076\u0042\u0065\u0032\u005c\u004f\u0047\u0048\u0057\u002c\u0026\u0043\u004c\u0070\u0026\u007a\u0061\u003d\u007e\u0020\u0057\u004e\u0065\u0042\u0042\u0020\u006d\u0078\u0061\u004d\u0051\u0035\u005f\u002a\u0025\u005e\u0039\u0027\u007d\u004c\u0038\u0050\u006a\u0063\u0035\u0030\u002b\u0027\u0032\u002e\u0052\u002b\u0051\u0079\u0022\u005e\u0044\u0074\u0040\u0022\u0028\u003f\u0066\u006f\u0051\u0036\u004f\u0029\u0043\u005b\u0032\u0024\u0028\u003d\u0042\u0043\u0049\u0039\u0070\u0042\u002b\u007e\u007a\u0047\u002c\u004d\u0076\u002c\u0042\u004b\u0077\u0066\u004c\u0059\u0067\u0022\u002f\u0079\u005e\u0067\u0049\u0052\u002b\u0068\u0036\u004b\u0044\u0053\u0040\u002e\u005a\u0073\u0027\u005c\u0022\u0025\u004f\u003f\u006e\u005b\u0064\u0060\u007c\u007b\u0033\u0026\u004e\u005c\u0029\u0071\u003d\u0025\u006b\u005e\u006b\u005d\u0067\u0075\u005a\u0029\u0073\u004b\u0063\u0043\u0061\u0044\u0051\u0044\u006c\u007d\u003d\u005e\u003f\u0065\u0078\u003c\u0064\u004a\u005c\u0045\u0026\u0034\u003a\u0033\u005d\u007a\u0035\u0073\u002c\u005f\u003f\u0058\u0071\u0072\u0050\u006f\u002d\u0039\u0023\u0035\u0041\u0024\u005d\u006e\u0071\u002a\u0052\u007e\u0030\u0031\u0068\u003f\u0046\u0069\u0064\u0073\u0036\u002f\u002d\u0027\u0048\u0020\u0066\u0046\u0044\u006b\u006b\u0053\u0076\u0033\u0020\u0073\u003e\u0046\u002c\u0025\u0063\u0072\u0056\u0067\u003d\u0045\u0065\u0023\u0046\u0020\u0057\u007e\u0063\u0067\u0051\u0044\u003f\u0075\u007b\u0048\u0029\u0043\u004f\u0078\u005b\u004a\u0071\u0045\u004f\u005f\u0052\u0023\u0026\u0077\u0027\u0056\u0062\u0058\u006e\u005e\u0045\u006a\u0069\u0048\u0037\u0034\u0023\u002d\u004b\u006e\u0060\u0055\u004e\u0053\u0071\u003d\u004a\u0057\u005d\u006c\u003f\u0043\u006f\u0030\u0025\u0031\u0039\u0024\u006f\u0020\u006e\u0049\u0050\u003d\u0058\u0069\u0063\u005b\u006f\u0043\u003d\u006d\u003b\u006b\u0036\u0063\u0068\u0077\u0079\u0051\u002d\u0073\u0063\u0073\u0025\u004a\u0074\u005d\u0032\u004e\u0062\u0052\u007b\u0030\u002e\u0064\u005c\u007b\u0065\u0063\u003e\u0038\u0074\u0068\u0061\u0078\u0021\u0043\u0070\u0026\u0061\u0079\u0056\u0078\u007a\u0066\u0079\u0062\u0028\u005f\u0028\u0054\u0041\u0062\u0057\u003c\u007e\u007c\u0062\u0077\u007d\u0075\u002e\u0059\u0022\u002e\u005e\u002c\u0074\u0041\u007c\u0073\u0060\u0028\u0025\u002b\u0077\u0042\u0079\u0052\u005b\u0030\u0055\u0024\u0064\u006b\u0033\u0055\u002c\u005d\u0058\u0065\u0023\u0078\u0034\u007c\u006a\u0056\u0020\u0027\u0059\u0078\u0074\u0042\u002f\u0041\u0036\u002f\u0055\u0073\u004d\u007b\u0077\u0043\u006a\u002e\u005e\u002b\u007c\u0049\u0044\u005c\u0032\u0075\u0058\u0049\u004e\u002f\u002c\u0069\u0020\u0038\u004f\u006a\u007b\u0052\u004f\u003a\u005e\u002e\u0034\u003f\u0026\u0032\u0044\u007c\u0076\u0076\u0055\u0021\u0041\u0045\u0026\u006e\u002f\u0033\u004d\u0031\u0049\u0044\u0065\u0066\u002e\u003d\u005a\u005a\u0040\u002a\u004e\u0073\u004b\u0076\u0023\u0060\u003c\u005e\u0076\u0034\u0053\u0036\u0059\u0045\u006c\u007a\u0065\u007a\u0033\u0074\u0066\u005c\u004e\u0022\u006a\u0025\u002e\u0021\u0044\u007a\u0074\u0073\u0063\u0065\u0056\u004d\u002e\u0034\u004c\u0069\u0046\u0068\u002a\u003c\u0020\u0044\u0042\u007c\u0029\u0076\u002e\u0077\u006c\u0030\u0051\u005a\u006a\u0077\u007b\u0055\u0026\u0076\u0030\u0029\u0040\u007d\u0033\u003a\u0029\u0066\u0037\u004f\u0021\u0030\u0046\u0021\u0057\u0037\u0057\u005e\u0027\u0076\u0079\u0045\u0023\u002b\u007a\u003a\u0053\u0070\u006b\u0038\u007d\u003c\u005e\u0059\u0043\u0055\u0057\u004f\u006b\u0028\u007b\u006b\u0029\u0067\u0055\u006e\u004e\u0038\u004d\u003e\u006a\u004d\u0050\u005e\u0046\u004d\u005e\u0078\u002f\u0026\u003a\u0057\u007e\u0068\u004f\u002c\u003f\u0041\u006f\u0060\u0063\u0020\u0032\u0066\u0065\u0022\u0042\u0022\u007b\u0041\u004b\u005f\u0029\u004f\u0024\u0029\u0025\u005b\u005d\u0042\u0051\u0074\u0057\u003e\u0073\u005f\u0021\u006d\u0079\u0031\u0076\u0065\u004a\u0040\u003a\u0077\u0031\u0056\u0074\u004d\u002e\u0052\u004f\u0064\u0052\u003c\u0025\u0031\u006f\u0051\u002d\u0075\u0040\u0030\u0033\u0077\u0064\u0045\u0077\u007d\u0021\u0070\u0049\u003d\u0041\u004b\u0067\u007c\u002e\u005f\u0044\u0056\u005d\u0072\u0039\u005b\u0067\u0077\u004d\u0049\u005f\u0045\u007b\u0042\u003a\u004c\u0024\u0052\u0069\u002e\u007a\u0052\u005f\u004b\u0076\u0034\u0059\u006a\u0051\u0044\u0054\u0074\u0058\u0020\u003f\u0030\u0074\u0060\u0079\u0024\u0054\u0045\u0079\u005a\u0029\u005e\u0023\u0041\u0078\u0058\u007b\u0050\u005d\u0075\u0067\u003f\u006f\u0029\u0062\u0076\u002c\u002b\u0053\u0029\u005a\u006c\u0072\u006e\u0077\u0028\u0075\u002f\u0077\u003b\u0038\u0053\u0020\u006b\u007d\u0035\u0038\u006e\u002a\u0053\u0064\u0062\u0022\u0048\u0068\u0046\u005f\u0057\u0055\u0026\u0046\u007c\u002e\u002d\u003e\u0039\u0031\u006d\u0064\u0053\u006d\u0062\u0074\u005a\u0070\u004e\u0048\u003b\u004b\u0029\u006a\u0040\u0037\u0079\u002c\u0041\u0022\u0063\u007d\u005f\u0027\u004d\u0042\u005b\u002c\u0032\u0031\u0044\u004f\u0070\u002b\u004b\u0073\u004d\u003f\u007e\u0064\u0067\u002a\u003d\u0042\u005b\u0057\u0068\u0059\u0062\u0052\u0040\u002d\u0075\u0031\u0066\u0065\u0028\u007c\u0021\u0054\u003d\u0075\u0054\u0030\u0075\u0038\u0024\u004c\u007e\u0034\u007b\u0030\u0076\u006d\u0025\u0062\u0029\u007c\u0048\u004a\u0041\u004b\u0065\u0020\u0023\u0053\u0026\u0044\u007d\u007c\u003e\u002a\u0040\u005d\u0030\u003e\u003b\u0064\u0076\u0044\u0021\u0043\u002a\u003b\u0079\u0065\u005d\u0054\u0064\u002e\u0078\u0069\u007e\u0053\u003d\u006d\u007b\u002c\u0068\u0037\u0033\u0035\u0028\u004c\u0048\u002d\u0046\u0048\u0067\u0037\u0058\u005a\u0043\u002f\u0079\u0063\u0063\u0034\u0076\u0070\u005a\u0060\u0041\u0030\u0069\u006b\u0070\u006d\u007b\u005b\u0062\u003c\u007e\u002a\u0020\u0052\u0055\u0025\u0078\u0051\u007a\u0024\u0049\u0042\u0072\u0042\u0037\u0036\u0067\u0030\u0048\u0057\u0059\u0043\u002e\u0026\u003b\u0042\u0023\u007e\u007a\u0043\u0026\u0028\u002c\u0037\u007c\u0070\u0071\u0056\u0045\u0066\u002e\u0055\u0024\u005a\u0048\u002e\u0073\u007a\u0029\u0061\u0053\u005b\u002a\u0057\u0066\u005a\u0043\u003d\u0057\u003b\u003c\u0057\u0050\u0072\u0030\u005b\u003c\u007b\u0064\u0054\u0045\u004d\u005a\u0045\u004d\u0053\u0079\u002e\u003b\u0065\u006e\u004f\u0023\u0020\u004b\u006c\u004a\u0060\u0077\u0022\u002f\u0069\u0028\u004a\u0027\u0041\u0034\u005a\u0043\u0047\u0067\u0030\u0023\u006a\u004d\u006e\u005e\u004e\u006b\u0079\u004c\u0079\u0053\u0036\u0025\u0029\u0058\u002b\u0068\u0066\u004d\u0057\u0038\u004b\u0078\u0036\u005a\u004b\u003c\u002b\u005e\u0036\u0054\u0029\u0065\u0027\u0063\u0059\u0073\u0030\u002c\u006d\u0049\u007a\u003c\u006d\u006d\u0029\u0045\u0069\u0043\u0076\u0023\u003b\u004c\u0049\u0046\u005a\u0061\u002d\u0047\u004e\u0052\u005b\u0039\u0069\u0037\u005f\u0026\u0041\u0067\u0066\u0025\u006b\u0024\u0062\u0051\u003e\u0027\u0052\u0045\u0045\u0035\u0048\u005b\u0075\u004a\u0025\u0060\u004c\u007a\u0079\u0057\u0040\u0028\u002f\u004e\u002d\u0020\u0042\u0055\u0029\u0023\u0058\u0054\u0077\u002a\u002b\u0033\u005c\u0078\u003b\u004e\u005b\u0034\u003c\u003b\u0057\u0067\u004f\u002f\u0037\u0027\u0027\u0036\u0063\u007e\u0050\u007e\u003c\u007a\u0064\u0067\u005a\u0052\u0066\u002e\u0071\u0073\u006a\u007d\u0037\u0059\u004c\u0025\u003a\u0033\u006c\u003e\u0070\u0073\u0059\u0066\u004d\u005e\u0077\u0033\u006e\u0075\u002b\u0026\u0049\u0041\u0057\u0067\u004a\u0055\u0021\u0050\u003e\u0056\u0075\u0042\u005b\u0041\u0026\u003e\u0041\u0077\u0030\u0021\u007a\u007d\u0056\u0077\u0067\u0038\u0056\u004c\u0078\u0076\u002a\u0037\u0065\u0029\u0060\u006e\u0051\u0063\u0035\u005b\u003a\u0030\u0064\u0069\u003f\u0063\u0022\u0060\u003b\u003f\u005d\u0076\u0072\u006a\u0070\u004e\u004a\u002a\u0025\u0031\u005a\u007d\u0077\u0058\u0028\u0028\u006e\u003a\u007c\u0035\u0050\u0069\u002b\u0070\u0025\u0021\u0076\u004f\u0064\u0025\u0042\u005d\u0078\u0069\u0057\u0079\u004a\u005e\u0043\u006e\u0057\u007c\u004e\u0034\u0025\u0045\u005d\u0037\u0034\u005d\u004b\u004f\u003e\u0022\u007e\u002a\u0069\u0022\u0034\u0028\u0051\u0071\u0023\u0048\u0046\u0038\u006a\u0069\u002f\u002a\u007c\u0025\u002c\u0067\u0072\u0054\u0075\u0045\u0038\u0048\u0064\u0050\u002f\u0042\u002d\u003f\u004b\u0026\u0043\u0048\u0036\u0021\u0071\u0028\u0035\u0021\u004c\u0029\u002f\u004a\u0058\u0065\u003f\u0062\u0021\u0021\u0076\u0030\u002b\u0055\u0047\u0071\u0074\u0032\u0058\u0071\u0030\u0047\u0020\u0052\u005c\u006d\u002f\u004a\u0056\u0031\u005e\u0048\u005a\u0055\u0062\u0057\u0071\u002e\u006a\u003b\u003f\u002b\u006e\u0028\u0069\u0040\u0053\u0043\u006c\u0052\u004e\u002a\u0031\u0068\u005f\u0069\u0065\u0020\u0023\u0027\u0055\u005e\u0047\u0047\u0045\u004f\u0036\u006f\u003a\u002e\u004d\u002e\u0074\u0070\u0050\u003e\u0040\u0020\u0027\u0078\u004d\u0050\u0022\u0054\u0061\u004a\u0022\u002f\u005b\u0021\u0058\u006b\u0068\u0020\u005f\u006c\u002a\u007e\u0025\u0063\u0030\u0056\u006c\u003d\u0056\u0023\u004d\u0022\u0059\u0026\u0056\u0022\u0039\u007e\u0072\u0020\u0068\u0065\u0079\u0038\u0022\u0049\u0066\u007e\u0029\u0062\u0072\u0076\u0058\u002c\u003b\u0076\u005a\u0026\u006d\u005e\u004c\u0055\u0061\u0025\u0063\u0059\u0030\u0071\u003f\u0029\u002d\u0042\u0054\u006d\u006a\u0071\u0062\u0037\u0072\u005d\u003a\u0056\u004f\u007a\u0062\u0057\u0063\u003c\u0062\u0037\u0061\u005e\u006d\u0073\u0037\u0031\u0041\u0030\u0031\u006b\u003a\u0044\u003e\u0032\u004d\u004c\u003e\u0031\u0046\u006a\u0050\u0059\u0076\u0070\u0038\u0041\u005f\u007d\u0032\u0065\u0067\u0055\u002e\u0078\u0072\u0052\u0050\u007e\u007e\u0050\u003c\u0061\u002d\u005d\u0024\u007e\u006f\u0077\u0026\u005b\u0043\u0024\u0050\u002c\u002c\u004b\u006e\u003a\u0059\u004d\u0028\u0068\u0020\u0035\u0026\u003f\u0053\u006d\u0036\u0055\u005a\u005a\u0046\u007e\u0050\u005c\u0041\u0070\u0048\u0076\u006b\u0070\u006d\u002f\u003f\u002e\u0034\u004c\u004c\u0046\u0076\u006a\u002b\u004b\u0025\u002c\u002f\u0039\u007e\u004b\u0059\u0061\u0060\u007e\u0024\u0032\u0071\u0071\u0071\u005a\u0035\u0060\u002d\u0068\u007a\u0021\u0042\u0078\u0062\u0076\u003e\u0060\u0061\u0044\u0077\u004e\u0023\u0064\u007a\u0073\u0036\u0058\u0023\u0054\u0041\u0048\u0070\u0073\u004e\u0054\u0023\u002e\u0070\u0028\u005d\u0075\u0050\u0068\u005b\u0072\u006e\u0031\u0064\u0048\u002d\u0077\u0042\u0075\u002d\u0061\u005d\u0020\u0064\u002f\u003d\u0044\u0070\u0032\u0039\u006d\u003c\u002c\u0065\u0070\u002a\u0022\u0029\u0074\u005d\u0029\u0049\u0078\u0078\u0076\u005c\u0050\u0071\u004b\u004a\u0059\u005d\u006d\u0067\u0077\u0063\u0043\u004b\u006d\u005d\u0026\u0074\u0035\u006a\u0026\u004e\u007e\u002f\u0047\u0058\u004b\u0023\u002f\u0075\u002d\u0026\u002a\u0059\u0054\u0071\u007b\u0062\u0039\u0033\u0022\u005b\u0052\u006c\u004d\u005b\u0023\u0062\u0037\u0055\u0053\u002a\u005a\u0079\u007b\u005d\u0072\u0038\u0057\u0068\u0031\u006b\u0035\u0023\u0036\u005a\u0049\u0063\u0025\u003d\u007a\u0021\u0064\u0068\u0033\u0028\u0069\u0079\u0075\u006b\u002e\u0025\u006f\u0045\u007b\u005e\u0057\u007e\u0055\u0079\u007d\u0064\u0072\u005f\u0045\u002a\u0033\u004c\u004f\u007a\u005f\u005a\u0061\u0049\u0037\u006e\u0051\u0046\u0047\u006a\u0052\u0073\u002b\u0032\u0030\u0043\u003c\u0053\u0024\u0047\u004d\u0051\u007c\u0028\u0055\u002a\u0025\u0044\u005f\u0058\u0061\u007e\u0062\u0077\u0035\u0069\u0022\u007e\u0054\u002c\u002e\u0037\u005e\u003b\u0073\u0045\u007e\u0079\u007c\u0052\u004a\u0054\u0051\u0074\u003a\u0029\u0060\u005f\u007a\u0060\u0022\u002e\u0077\u004e\u007b\u0072\u0036\u0021\u0025\u0070\u003f\u007e\u0074\u0077\u007d\u003d\u0066\u0033\u006f\u006b\u007b\u002b\u0039\u0076\u005e\u003b\u0027\u0056\u002b\u006e\u006b\u005c\u007e\u0038\u0033\u0069\u0058\u0063\u004c\u0026\u0079\u0041\u0050\u005c\u0032\u003f\u0047\u0063\u0036\u0075\u0032\u004b\u007b\u002a\u0042\u0064\u0070\u0056\u007c\u007e\u0050\u005a\u0049\u0065\u007e\u0065\u0063\u0024\u0067\u006f\u0061\u003f\u0051\u0028\u0051\u0028\u0044\u0050\u007e\u0035\u0030\u0055\u004f\u0037\u004c\u003c\u006a\u003a\u0057\u005e\u006b\u0048\u007d\u0079\u002e\u0044\u004c\u0068\u0050\u0052\u0060\u0038\u004a\u0045\u004c\u0025\u0059\u0074\u002f\u0060\u0073\u0043\u002e\u0071\u006c\u0061\u006b\u0077\u0021\u0071\u006c\u0042\u002d\u004e\u0024\u007d\u0060\u0068\u004f\u004a\u006e\u0051\u007e\u0077\u0046\u003d\u0078\u002b\u0052\u004a\u0031\u0060\u005f\u0076\u004d\u0035\u0022\u003e\u002d\u0058\u0034\u0021\u0026\u0028\u006b\u0075\u0059\u003d\u0069\u0066\u0075\u0052\u005e\u0027\u002d\u004d\u0064\u0022\u0071\u0048\u004f\u0070\u0046\u0048\u007b\u003d\u0020\u0060\u002a\u006f\u005a\u0066\u0077\u0050\u0023\u0027\u0077\u0025\u0023\u0047\u0061\u005a\u0054\u005b\u004c\u0069\u0036\u004f\u003a\u0033\u003e\u0069\u0059\u007b\u0056\u0058\u0043\u002d\u0051\u002b\u004f\u0024\u007e\u004f\u0067\u0059\u0059\u0070\u004b\u004b\u002f\u0056\u002f\u0052\u0031\u003b\u0066\u0056\u002a\u0035\u005a\u0070\u004a\u004a\u003f\u006c\u0039\u003a\u003b\u0064\u002d\u0028\u0021\u0060\u0037\u0029\u0048\u002c\u0028\u0053\u0052\u0052\u0055\u004b\u0021\u0039\u006d\u006c\u0058\u0026\u0067\u004b\u0026\u005d\u002e\u0048\u0043\u006c\u005b\u0051\u0034\u0052\u004b\u0075\u0047\u004a\u0070\u0047\u007b\u004a\u004b\u007e\u0055\u005a\u0077\u0078\u006f\u002f\u0077\u0036\u0024\u006c\u006f\u0041\u0030\u0047\u0067\u002b\u0051\u007c\u006a\u0047\u002f\u003d\u0028\u0050\u0053\u003d\u0059\u0059\u0073\u006a\u0029\u0070\u0051\u0034\u0026\u0056\u0048\u0078\u0053\u006a\u007e\u006b\u0079\u004d\u002f\u0048\u005e\u0058\u0068\u0078\u0022\u0068\u004b\u007e\u0051\u0020\u006c\u006b\u0068\u0043\u0048\u002a\u0070\u0034\u004d\u0075\u006c\u0057\u0037\u0037\u007b\u007e\u0078\u006b\u0075\u0070\u004f\u004e\u0040\u0064\u006c\u0072\u0047\u0020\u0028\u006c\u007a\u0020\u0058\u006c\u0067\u0033\u003b\u007b\u004f\u005b\u004d\u0056\u0043\u007c\u005d\u0058\u0072\u0074\u0036\u0050\u0024\u0022\u0061\u0024\u0038\u0037\u0066\u0056\u002a\u0042\u002c\u007d\u007d\u0029\u003c\u0027\u0067\u007a\u0073\u0065\u0021\u004f\u005b\u0078\u0022\u0041\u002c\u005c\u004b\u002c\u0054\u003e\u003e\u0027\u0070\u002e\u0057\u002c\u003e\u002a\u0069\u0060\u006c\u0024\u0078\u003e\u002e\u0069\u0057\u0052\u0074\u0053\u005a\u0050\u002f\u0064\u002d\u0026\u003b\u003e\u0057\u0035\u0078\u0031\u0041\u0058\u0047\u0055\u002a\u0057\u0050\u0068\u0039\u004b\u005b\u0033\u0065\u0049\u0021\u0075\u0021\u0045\u0068\u006f\u006b\u0022\u0077\u003d\u0064\u0043\u0020\u0043\u0045\u0061\u0065\u003c\u0033\u0051\u005e\u0044\u0052\u006d\u003a\u0045\u0065\u0054\u0054\u007a\u0048\u0038\u0037\u003d\u006b\u0035\u0042\u0070\u007d\u006e\u0062\u002e\u007a\u0057\u007e\u0059\u005f\u0070\u0062\u0040\u003c\u003c\u0052\u0073\u002a\u004f\u0077\u0023\u0064\u006b\u0063\u0030\u006d\u0068\u0026\u0059\u004e\u0070\u0063\u004b\u007d\u0058\u0065\u007d\u0044\u004a\u0034\u0053\u0064\u007d\u005e\u003a\u004c\u0032\u0039\u006b\u0077\u0053\u0077\u007d\u003c\u0043\u0034\u0029\u005b\u004d\u0034\u0066\u0020\u0068\u004c\u0044\u0045\u0020\u005d\u0056\u0046\u0062\u0030\u0032\u0037\u006e\u0048\u0025\u0031\u006a\u0068\u0029\u0058\u0026\u0029\u002f\u0052\u005e\u0023\u003a\u007c\u0050\u0071\u0026\u004e\u003a\u002b\u004f\u0068\u0027\u0026\u0022\u0037\u0028\u005d\u007e\u007a\u0069\u003b\u0057\u004d\u0066\u005e\u005c\u0069\u0067\u005c\u0063\u0050\u0068\u002a\u0076\u004a\u0028\u007c\u0030\u0034\u0023\u0060\u0026\u002b\u0077\u007d\u003a\u0059\u0026\u0023\u0062\u0039\u0046\u0028\u003e\u004b\u0063\u0033\u005b\u0057\u0075\u002f\u003f\u0046\u0025\u0040\u0053\u0054\u0026\u0035\u007d\u007d\u0061\u0066\u006a\u0060\u003f\u0037\u0044\u0050\u005c\u003e\u0031\u0040\u003e\u0061\u004f\u006d\u0034\u0043\u003e\u006b\u0035\u003e\u007a\u0054\u0040\u0071\u006a\u0046\u0057\u002f\u0062\u003b\u005d\u0064\u0030\u0074\u0065\u0055\u007e\u007a\u006b\u0023\u0077\u0043\u0079\u0063\u006c\u0066\u0034\u0040\u0064\u002e\u0049\u0063\u0073\u004d\u0024\u0074\u0041\u0075\u003b\u0068\u006d\u005a\u007b\u002c\u0078\u0040\u0022\u005f\u003c\u0025\u004b\u0073\u0046\u0041\u0022\u0053\u0030\u0057\u002e\u007a\u0050\u0068\u0026\u0045\u0024\u0029\u0078\u005b\u0032\u004b\u0063\u0038\u002d\u002b\u004b\u0046\u006a\u0039\u0057\u0034\u005d\u0067\u004f\u0022\u0069\u0027\u0075\u0060\u0028\u0053\u0039\u002a\u0036\u002c\u0069\u0068\u0064\u003c\u005f\u004e\u006c\u005f\u0032\u0070\u0029\u0063\u006a\u006f\u005a\u0073\u0046\u0027\u0055\u002e\u0025\u007e\u0052\u002a\u0054\u006d\u0046\u0056\u0071\u0060\u0057\u0026\u003f\u0060\u004d\u0064\u006c\u0042\u0047\u0055\u005f\u007b\u0078\u0031\u0063\u0033\u0050\u0067\u005a\u0041\u004f\u0020\u005d\u0064\u0070\u0021\u0064\u005f\u004f\u0024\u0072\u0053\u0030\u0067\u0078\u0061\u0038\u0064\u006b\u0029\u0056\u0070\u0053\u0076\u0035\u0032\u002d\u0051\u0050\u007e\u003c\u0035\u003d\u004e\u0034\u002c\u002c\u007e\u006c\u004c\u0073\u0072\u0075\u0076\u0049\u004b\u0069\u0047\u0046\u004b\u006e\u0063\u0049\u0066\u005c\u0055\u0069\u0031\u0021\u005e\u0070\u006a\u007a\u006b\u0038\u0022\u002f\u007d\u0033\u007d\u0020\u0056\u002f\u0021\u0031\u0020\u004c\u0069\u0058\u0052\u007d\u0042\u0042\u003d\u007e\u0074\u0069\u0064\u0037\u0038\u0056\u003f\u0052\u0022\u0041\u007e\u0071\u0068\u0028\u0065\u0043\u004a\u0056\u0041\u007e\u005b\u0044\u0056\u007c\u005a\u006b\u0028\u002a\u0058\u0026\u0034\u0047\u0040\u0051\u003c\u0066\u0035\u0033\u0047\u007d\u002d\u004f\u002c\u0050\u0023\u0053\u0044\u005b\u0023\u0071\u0054\u002a\u0037\u007b\u0071\u0077\u0077\u007e\u0049\u006a\u0022\u006c\u0059\u0044\u003a\u0076\u005b\u0062\u0079\u0031\u0072\u0036\u002b\u0077\u0050\u007a\u0029\u006c\u0030\u007c\u0043\u0075\u0045\u0071\u0079\u003c\u002b\u0033\u0066\u004b\u0051\u003a\u0033\u0037\u0044\u007a\u0022\u006d\u0033\u0052\u0043\u003f\u0078\u0055\u0038\u003f\u0058\u0065\u0049\u002c\u0064\u0033\u002a\u0046\u0029\u0065\u004e\u007d\u004b\u003a\u0047\u0021\u0078\u006c\u0034\u002b\u0025\u0032\u006f\u007a\u0072\u0041\u0043\u004e\u0069\u0023\u0065\u0047\u0062\u0058\u0057\u0040\u0054\u0026\u005e\u003d\u0037\u0031\u003f\u0028\u006a\u0052\u0066\u0043\u0074\u0078\u0020\u006c\u005b\u0076\u003d\u0059\u0024\u003f\u0065\u0044\u0057\u0069\u002a\u0034\u0024\u003e\u003b\u0076\u006a\u002e\u0056\u0023\u0024\u0062\u0052\u0047\u006a\u0042\u005b\u0069\u0060\u0022\u0072\u003c\u004c\u0034\u004b\u0033\u005a\u003d\u007a\u0047\u006f\u0035\u0070\u004a\u0035\u005e\u003b\u007b\u004b\u007a\u002c\u0069\u0052\u002e\u0078\u0046\u004d\u0042\u0044\u004c\u004c\u0059\u0075\u007a\u005e\u004d\u0046\u0024\u0032\u0021\u0069\u0026\u0023\u005f\u005a\u002e\u0044\u0074\u0064\u005f\u0027\u0043\u003e\u0068\u004c\u003e\u0027\u005e\u0049\u005c\u0024\u0024\u003a\u0022\u0056\u0067\u0021\u0072\u0030\u0042\u0020\u0041\u0027\u003f\u0048\u0031\u0034\u0067\u004b\u0069\u0028\u0052\u0039\u0041\u0059\u0028\u0061\u003e\u0024\u007e\u0034\u007d\u0046\u0061\u006c\u002d\u0072\u0041\u0067\u0056\u006c\u004d\u005e\u0061\u0047\u004e\u0077\u007b\u0070\u006c\u004c\u006e\u004c\u007d\u007c\u006e\u006b\u0048\u0045\u0038\u003d\u0046\u005a\u0022\u0034\u0031\u0054\u0046\u0056\u0069\u0025\u0031\u0043\u0039\u007a\u0071\u002b\u0069\u002f\u0072\u005e\u0058\u006c\u007d\u007c\u0020\u0030\u007d\u0034\u005f\u0068\u002f\u0024\u004f\u0069\u005b\u0074\u0068\u0021\u0023\u0029\u0071\u0034\u0041\u0071\u0072\u0069\u0075\u0035\u0021\u002d\u0024\u002e\u0022\u003d\u0039\u003a\u0064\u0070\u006e\u0047\u0034\u0035\u006d\u0022\u005a\u0030\u006a\u0041\u0065\u0027\u0050\u0027\u005b\u0043\u002e\u0038\u0078\u0076\u0070\u003a\u0078\u002e\u0029\u006e\u0058\u0040\u0020\u0037\u0059\u0073\u003d\u0021\u003d\u005a\u006e\u0021\u0064\u003c\u003d\u007c\u002d\u0057\u0026\u0030\u0044\u006f\u0061\u002b\u0069\u005d\u002f\u006a\u0065\u0034\u0047\u003d\u006d\u003c\u0020\u002a\u005b\u0044\u0041\u004d\u007c\u0020\u0046\u003f\u0035\u006e\u0072\u0021\u0054\u0046\u0047\u0048\u0056\u0043\u007a\u003b\u0048\u005f\u0074\u0054\u0050\u004c\u0035\u003e\u0068\u0051\u002e\u0023\u007d\u002d\u003a\u0043\u0069\u0029\u003f\u0061\u0036\u006b\u005a\u006a\u0039\u003f\u006e\u0047\u005d\u004a\u0079\u0020\u0073\u0050\u0071\u0038\u005f\u0026\u0078\u0044\u0032\u0074\u0078\u006e\u0047\u003b\u0058\u005f\u007c\u003e\u0045\u0039\u0021\u0057\u0047\u0020\u005d\u003b\u0065\u0047\u0039\u007e\u0033\u0041\u0022\u0057\u0058\u0026\u0075\u003b\u0078\u0061\u004c\u002d\u006e\u0078\u0051\u0025\u0070\u005d\u0024\u0043\u0035\u0059\u0038\u0062\u0028\u0048\u004c\u005f\u0075\u007b\u004f\u006e\u0035\u0034\u005a\u0059\u004c\u005b\u003b\u0058\u0048\u0024\u0022\u0065\u0043\u0064\u007a\u006f\u0057\u007b\u005f\u0045\u0055\u0068\u0031\u0044\u0032\u0068\u0060\u0034\u006c\u0032\u0071\u0076\u0037\u0075\u002f\u0024\u005a\u0065\u0065\u0075\u0021\u0068\u0041\u0035\u0073\u0030\u002d\u0054\u003d\u0051\u0079\u0026\u0054\u002a\u0037\u003e\u0049\u0023\u006f\u0057\u003a\u002d\u0038\u003f\u0078\u0059\u0068\u006b\u0066\u0044\u007c\u0076\u0076\u005a\u003d\u002c\u0049\u004b\u007c\u0077\u0035\u0024\u0069\u0030\u0076\u0033\u0044\u0024\u0055\u003f\u0025\u007d\u0065\u007e\u0020\u0060\u005f\u004e\u0036\u003a\u0025\u0034\u003a\u0047\u0023\u0075\u002d\u0035\u005f\u0042\u006c\u0057\u006d\u0024\u006a\u0028\u002b\u0048\u005b\u0065\u006c\u0021\u002e\u0040\u0060\u0032\u0022\u003c\u004a\u0041\u006f\u0068\u003c\u0031\u0068\u0065\u002f\u0055\u006d\u005e\u007c\u0064\u0064\u003c\u0020\u0043\u002f\u0067\u0047\u007c\u006e\u0025\u0076\u0038\u0065\u006f\u0070\u006b\u006f\u0073\u0051\u0066\u007b\u0066\u007b\u0056\u0025\u0075\u0066\u0043\u006a\u005a\u0048\u0021\u0060\u0028\u0060\u0041\u0066\u006e\u004d\u0059\u0038\u005d\u005f\u0057\u0030\u0061\u0066\u0055\u0020\u004f\u006d\u0067\u002b\u0049\u0050\u003e\u0033\u0051\u0039\u0058\u0062\u0038\u0047\u005c\u0032\u002f\u0050\u0033\u005c\u006c\u0040\u0076\u0069\u0048\u0048\u0027\u0076\u0074\u0039\u0042\u0048\u0054\u0050\u004b\u007c\u002c\u0041\u0026\u004a\u0032\u0074\u003f\u0031\u002b\u004f\u0042\u004b\u003b\u0027\u0061\u0033\u0069\u0066\u0060\u005a\u0036\u0044\u0072\u0051\u002a\u0042\u005d\u0035\u0044\u0067\u006e\u0033\u0024\u0042\u004a\u003b\u005f\u0030\u0079\u006b\u0046\u002f\u0075\u004c\u0049\u004d\u0059\u0078\u0037\u0052\u0067\u0044\u0045\u003e\u0047\u002e\u0051\u003a\u005e\u002b\u005a\u002d\u0053\u0078\u004d\u0030\u005c\u0041\u0048\u0021\u0020\u002b\u002d\u0062\u0064\u0035\u0033\u004d\u0048\u005a\u006f\u0066\u0021\u002d\u002f\u0040\u004d\u0046\u0047\u006b\u0040\u0035\u0028\u0039\u0038\u0061\u0040\u003b\u0039\u002f\u0043\u007d\u0062\u007c\u003b\u0020\u0056\u006f\u007b\u003c\u007d\u0066\u007e\u005c\u0041\u004b\u002b\u0030\u007c\u004e\u0050\u0023\u0035\u0074\u0033\u0072\u007d\u0032\u003f\u0048\u0050\u0022\u0061\u0044\u0049\u006e\u0061\u007e\u006b\u0042\u0064\u007d\u005c\u0056\u0028\u006c\u006a\u0039\u0063\u003b\u0042\u0065\u003f\u0043\u0067\u0048\u0039\u0046\u0062\u007d\u0045\u0028\u0077\u002f\u0051\u0046\u007c\u005e\u005a\u004b\u006a\u0034\u0022\u0064\u004f\u004d\u0040\u0064\u007d\u0025\u0073\u0044\u005e\u0033\u002d\u0039\u004a\u0047\u006c\u003e\u0079\u004d\u0063\u007c\u002d\u005d\u006f\u007c\u007d\u0024\u004a\u0052\u0061\u004a\u0058\u0061\u0046\u0067\u004c\u003e\u007b\u0051\u0033\u0056\u0058\u0058\u007b\u005e\u002e\u0067\u0054\u002e\u0022\u004f\u003f\u006e\u0030\u0068\u0079\u004c\u006d\u0023\u0059\u002f\u002b\u0034\u0029\u004d\u0061\u0053\u0065\u0060\u0042\u0039\u0036\u0078\u0054\u003a\u003d\u0049\u0079\u0047\u0074\u002d\u003d\u003f\u0047\u0078\u0055\u0053\u002a\u007a\u0048\u007a\u002b\u0063\u0069\u0046\u0066\u003a\u0030\u0028\u0022\u0076\u0076\u007d\u005e\u0043\u0074\u0053\u0032\u0040\u0032\u0079\u007e\u002e\u003a\u005d\u0058\u004e\u0034\u0039\u0053\u0043\u0035\u0066\u0068\u003d\u0034\u0032\u004f\u003c\u0068\u005f\u0053\u004f\u005f\u0041\u004a\u005c\u0077\u0041\u0056\u004d\u0037\u0021\u0043\u0030\u005c\u0073\u0054\u004e\u0050\u005f\u0076\u003a\u0041\u0035\u005c\u0020\u0068\u0050\u0027\u002f\u0063\u005a\u0077\u0051\u0047\u005a\u0050\u002c\u0071\u0037\u0022\u0070\u0039\u0043\u0035\u0050\u0027\u0065\u0077\u0067\u0066\u0058\u0047\u006b\u003e\u007d\u005c\u002e\u0036\u004e\u0078\u0029\u0057\u0032\u003e\u007e\u007c\u005b\u0058\u0032\u002b\u006c\u002a\u006a\u002a\u002a\u0077\u006a\u0067\u0075\u005e\u006e\u0071\u0021\u0051\u003e\u0037\u0055\u007e\u0044\u0064\u006c\u0073\u0037\u005e\u0068\u005c\u005b\u0062\u0025\u0070\u0068\u0020\u007e\u0061\u0038\u004a\u005e\u005c\u0035\u0037\u005b\u0059\u004d\u0027\u0032\u002b\u006a\u002e\u0024\u0075\u0040\u0068\u007d\u002d\u0052\u005c\u003a\u0075\u006c\u0032\u0047\u0047\u0026\u0046\u0038\u0066\u0044\u004f\u006c\u0038\u002f\u0026\u0050\u003a\u0051\u0048\u0068\u0059\u006a\u003c\u0022\u007d\u0039\u0064\u0021\u0048\u0038\u0042\u0076\u003f\u0045\u0035\u0066\u0042\u0059\u003b\u0021\u005c\u006a\u0068\u003c\u006d\u0036\u0071\u0038\u003a\u0073\u002c\u0026\u0025\u0045\u0024\u0026\u005e\u0046\u007c\u0063\u0020\u0060\u0061\u0036\u0066\u0048\u0062\u007b\u0045\u0026\u0043\u0063\u003f\u0058\u0068\u0070\u0040\u0045\u0046\u0037\u0034\u0069\u0077\u005c\u006a\u004b\u006c\u004f\u0067\u0053\u005d\u0024\u0058\u0051\u0042\u0069\u0027\u007b\u0070\u006b\u0030\u0029\u003c\u0021\u002b\u0071\u006a\u0079\u002b\u0075\u006b\u006b\u0053\u005c\u003c\u0050\u0048\u0040\u0070\u005c\u006a\u0060\u0062\u0020\u0078\u0039\u0026\u007c\u0043\u0075\u005b\u0049\u0020\u0059\u006b\u0039\u0024\u002d\u003d\u0021\u005b\u0066\u0058\u005a\u0042\u0046\u0020\u004a\u004e\u007a\u002c\u0060\u005a\u006b\u006f\u0039\u0038\u0046\u006d\u0027\u003b\u005e\u0069\u004b\u0052\u005c\u0068\u002b\u007c\u0048\u004e\u006d\u0045\u0034\u0079\u0069\u004f\u0044\u0049\u005c\u0060\u0030\u005b\u0020\u003f\u003c\u007b\u004a\u0022\u003b\u002f\u0054\u007c\u0020\u0042\u0046\u004e\u007d\u005f\u0034\u007d\u005d\u0062\u0065\u0020\u0067\u0026\u0022\u0055\u0078\u006b\u0049\u0032\u0064\u0027\u0054\u0055\u002c\u0034\u0027\u003f\u006a\u004d\u0022\u0029\u0049\u004e\u0075\u0034\u002d\u0074\u0062\u0025\u006c\u0046\u0021\u0036\u0061\u0059\u0073\u0079\u0020\u0064\u0074\u0078\u0038\u0073\u003c\u0038\u005b\u0056\u0035\u0051\u0034\u0023\u0046\u006c\u0060